{"edits":[{"path":"openclaw_runtime/src/agents/workspace-external-write-provenance-policy.ts","content":"/**
 * Workspace-external write provenance policy (S03 verification boundary).
 *
 * This module is the *single* boundary used by the runtime to decide whether a
 * write/edit/apply_patch request that targets a location outside of the
 * workspace may touch the filesystem at all.
 *
 * Contract implemented here:
 *  - Illegal provenance sources (`external`, `derived`, `invalid`, `missing`)
 *    are rejected *before* any filesystem mutation is attempted; the target
 *    file bytes are therefore never changed.
 *  - Trusted provenance sources (`trusted-system`, `direct-operator`) keep their
 *    previous semantics: the write is allowed and the resulting content is
 *    exactly what the caller asked for.
 *  - Path escapes (parent-directory traversal, absolute external paths,
 *    pre-existing symlink/junction aliases, hard links and win32 case
 *    variants) are all rejected for illegal provenance sources and leave the
 *    target untouched.
 *  - In-workspace write semantics are *not* changed by this module: requests
 *    whose target stays inside the workspace are out of scope for the external
 *    boundary.
 *  - Residual (UNC / device-namespace) paths cannot be triggered
 *    deterministically on every host; they are recorded explicitly as
 *    residuals instead of pretending they are covered.
 *
 * The module intentionally performs no network access and spawns no process.
 * It only performs read-only filesystem inspection (`lstat`/`realpath`) and,
 * for trusted sources, computes the resolved target path for the caller.
 */

import * as fsp from "node:fs/promises";
import * as path from "node:path";

export const EXTERNAL_WRITE_PROVENANCE_SOURCES = [
  "trusted-system",
  "direct-operator",
  "external",
  "derived",
  "invalid",
  "missing",
] as const;

export type ExternalWriteProvenanceSource =
  (typeof EXTERNAL_WRITE_PROVENANCE_SOURCES)[number];

/** Sources that are allowed to write outside of the workspace. */
export const TRUSTED_EXTERNAL_WRITE_SOURCES: readonly ExternalWriteProvenanceSource[] = [
  "trusted-system",
  "direct-operator",
];

/** Sources that are never allowed to write outside of the workspace. */
export const ILLEGAL_EXTERNAL_WRITE_SOURCES: readonly ExternalWriteProvenanceSource[] = [
  "external",
  "derived",
  "invalid",
  "missing",
];

/**
 * Explicitly recorded residuals: these path shapes cannot be triggered
 * deterministically on every host, therefore they are documented rather than
 * claimed as covered by the local test matrix.
 */
export const EXTERNAL_WRITE_POLICY_RESIDUALS: readonly string[] = [
  "unc-path",
  "device-namespace-path",
];

export type ExternalWritePathEscapeKind =
  | "none"
  | "parent-directory"
  | "absolute-external"
  | "alias-symlink-junction"
  | "hard-link"
  | "case-variant"
  | "unc-residual"
  | "device-namespace-residual";

export interface ExternalWriteProvenance {
  source: ExternalWriteProvenanceSource;
  /** Optional free-form actor identifier (never mutated by this module). */
  actor?: string;
  /** Optional free-form reason (never mutated by this module). */
  reason?: string;
}

export type ExternalWriteProvenanceInput =
  | ExternalWriteProvenanceSource
  | ExternalWriteProvenance
  | null
  | undefined;\n
export interface ExternalWritePolicyRequest {
  /** Provenance of the write request. */
  provenance?: ExternalWriteProvenanceInput;
  /** Target path of the write (absolute or relative to the workspace root). */
  targetPath: string;
  /** Root of the workspace; writes below it keep their existing semantics. */
  workspaceRoot: string;
}

export interface ExternalWritePathResolution {
  /** Lexically resolved absolute target path (no filesystem mutation). */
  requestedPath: string;
  /** Path after alias resolution when it could be determined. */
  resolvedPath: string;
  /** `true` when the target is considered outside of the workspace. */
  outsideWorkspace: boolean;
  /** Detected escape shape, `none` when the path is a plain workspace path. */
  escapeKind: ExternalWritePathEscapeKind;
  /** Residuals that apply to this path, if any. */
  residuals: string[];
}

export type ExternalWriteDecision =
  | {
      allowed: true;
      source: ExternalWriteProvenanceSource;
      resolution: ExternalWritePathResolution;
    }
  | {
      allowed: false;
      source: ExternalWriteProvenanceSource;
      code: string;
      reason: string;
      escapeKind: ExternalWritePathEscapeKind;
      residuals: string[];
    };

export class ExternalWritePolicyError extends Error {
  readonly code: string;
  readonly source: ExternalWriteProvenanceSource;
  readonly escapeKind: ExternalWritePathEscapeKind;
  readonly residuals: readonly string[];
  readonly targetPath: string;

  constructor(
    message: string,
    details: {
      code: string;
      source: ExternalWriteProvenanceSource;
      escapeKind: ExternalWritePathEscapeKind;
      residuals?: readonly string[];
      targetPath: string;
    },
  ) {
    super(message);
    this.name = "ExternalWritePolicyError";
    this.code = details.code;
    this.source = details.source;
    this.escapeKind = details.escapeKind;
    this.residuals = details.residuals ? [...details.residuals] : [];
    this.targetPath = details.targetPath;
  }
}

function isWindowsLike(): boolean {
  return process.platform === "win32";
}

function normalizeComparable(value: string): string {
  const normalized = path.normalize(value);
  return isWindowsLike() ? normalized.toLowerCase() : normalized;
}

function isInsideRoot(candidate: string, root: string): boolean {
  const normalizedCandidate = normalizeComparable(candidate);
  const normalizedRoot = normalizeComparable(root);
  if (normalizedCandidate === normalizedRoot) {
    return true;
  }
  const rootWithSep = normalizedRoot.endsWith(path.sep)
    ? normalizedRoot
    : normalizedRoot + path.sep;
  return normalizedCandidate.startsWith(rootWithSep);
}

/**
 * Normalize a caller supplied provenance value. Unknown / absent values are
 * mapped onto the explicit `invalid` / `missing` sources instead of being
 * silently treated as trusted.
 */
export function resolveExternalWriteProvenanceSource(
  input: ExternalWriteProvenanceInput,
): ExternalWriteProvenanceSource {
  if (input === null || input === undefined) {
    return "missing";
  }
  if (typeof input === "string") {
    return (EXTERNAL_WRITE_PROVENANCE_SOURCES as readonly string[]).includes(input)
      ? (input as ExternalWriteProvenanceSource)
      : "invalid";
  }
  if (typeof input === "object" && typeof input.source === "string") {
    return (EXTERNAL_WRITE_PROVENANCE_SOURCES as readonly string[]).includes(input.source)
      ? (input.source as ExternalWriteProvenanceSource)
      : "invalid";
  }
  return "invalid";
}

/** `true` only for the explicitly trusted provenance sources. */
export function isTrustedExternalWriteSource(
  input: ExternalWriteProvenanceInput,
): boolean {
  return TRUSTED_EXTERNAL_WRITE_SOURCES.includes(
    resolveExternalWriteProvenanceSource(input),
  );
}

/** `true` for every source that must never mutate a workspace-external target. */
export function isIllegalExternalWriteSource(
  input: ExternalWriteProvenanceInput,
): boolean {
  return ILLEGAL_EXTERNAL_WRITE_SOURCES.includes(
    resolveExternalWriteProvenanceSource(input),
  );
}

function detectResidualShape(target: string): { residuals: string[]; escapeKind: ExternalWritePathEscapeKind } {
  const residuals: string[] = [];
  let escapeKind: ExternalWritePathEscapeKind = "none";

  // Device namespace paths (\\?\C:\..., \\.\C:\...).
  if (/^[\\/]{2}\?[\\/]/.test(target) || /^[\\/]{2}\.\?[\\/]/.test(target)) {
    residuals.push("device-namespace-path");
    escapeKind = "device-namespace-residual";
    return { residuals, escapeKind };
  }

  // UNC paths (\\server\share\...).
  if (/^[\\/]{2}[^\\/]/.test(target)) {
    residuals.push("unc-path");
    escapeKind = "unc-residual";
    return { residuals, escapeKind };
  }

  return { residuals, escapeKind };
}

function lexicalTargetPath(targetPath: string, workspaceRoot: string): string {
  const root = path.resolve(workspaceRoot);
  if (path.isAbsolute(targetPath)) {
    return path.resolve(targetPath);
  }
  return path.resolve(root, targetPath);
}

function containsParentTraversal(targetPath: string): boolean {
  const segments = targetPath.split(/[\\/]+/);
  let depth = 0;
  for (const segment of segments) {
    if (segment === "..") {
      depth -= 1;
      if (depth < 0) {
        return true;
      }
      continue;
    }
    if (segment === "." || segment === "") {
      continue;
    }
    depth += 1;
  }
  return false;
}

async function realPathOrSelf(target: string): Promise<string> {
  try {
    return await fsp.realpath(target);
  } catch {
    return target;
  }
}

async function findAliasComponent(target: string): Promise<boolean> {
  const resolved = path.resolve(target);
  const parsed = path.parse(resolved);
  const segments = resolved
    .slice(parsed.root.length)
    .split(path.sep)
    .filter((segment) => segment.length > 0);

  let current = parsed.root;
  for (const segment of segments) {
    current = current.endsWith(path.sep) ? path.join(current, segment) : path.join(current, segment);
    try {
      const stats = await fsp.lstat(current);
      if (stats.isSymbolicLink()) {
        return true;
      }
    } catch {
      // Missing components cannot be aliases; keep scanning the remainder.
    }
  }

  const real = await realPathOrSelf(resolved);
  return normalizeComparable(real) !== normalizeComparable(resolved);
}

async function isHardLinked(target: string): Promise<boolean> {
  try {
    const stats = await fsp.lstat(target);
    return stats.isFile() && typeof stats.nlink === "number" && stats.nlink > 1;
  } catch {
    return false;
  }
}

/**
 * Resolve a target path against the workspace root, classifying the escape
 * shape. Read-only filesystem inspection is used for alias / hard-link
 * detection; the target file is never modified.
 */
export async function resolveWorkspaceExternalWritePath(
  targetPath: string,
  workspaceRoot: string,
): Promise<ExternalWritePathResolution> {
  const requestedPath = lexicalTargetPath(targetPath, workspaceRoot);
  const root = path.resolve(workspaceRoot);
  const residual = detectResidualShape(targetPath) ?? { residuals: [], escapeKind: "none" as ExternalWritePathEscapeKind };
  const residuals = [...residual.residuals];

  const rootReal = await realPathOrSelf(root);
  const lexicalInside = isInsideRoot(requestedPath, root);

  let escapeKind: ExternalWritePathEscapeKind = residual.escapeKind;
  if (escapeKind === "none") {
    if (!lexicalInside) {
      if (path.isAbsolute(targetPath)) {
        escapeKind = "absolute-external";
      } else if (containsParentTraversal(targetPath)) {
        escapeKind = "parent-directory";
      } else {
        escapeKind = "absolute-external";
      }
    } else if (containsParentTraversal(targetPath)) {
      escapeKind = "parent-directory";
    }
  }

  const alias = await findAliasComponent(requestedPath);
  if (alias && escapeKind === "none") {
    escapeKind = "alias-symlink-junction";
  }

  const hardLinked = await isHardLinked(requestedPath);
  if (hardLinked && escapeKind === "none") {
    escapeKind = "hard-link";
  }

  if (isWindowsLike() && escapeKind === "none") {
    const real = await realPathOrSelf(requestedPath);
    if (
      normalizeComparable(real) !== normalizeComparable(requestedPath) &&
      !normalizeComparable(real).startsWith(normalizeComparable(rootReal) + path.sep)
    ) {
      escapeKind = "case-variant";
    }
  }

  const resolvedPath = alias ? await realPathOrSelf(requestedPath) : requestedPath;

  const aliasEscapes = alias && !isInsideRoot(resolvedPath, rootReal);
  const outsideWorkspace =
    !lexicalInside || aliasEscapes || hardLinked || escapeKind === "case-variant";

  return {
    requestedPath,
    resolvedPath,
    outsideWorkspace,
    escapeKind,
    residuals,
  };
}

/**
 * Evaluate the external write boundary. The function never mutates the
 * filesystem, therefore a rejected request leaves the target file bytes
 * untouched.
 */
export async function decideWorkspaceExternalWrite(
  request: ExternalWritePolicyRequest,
): Promise<ExternalWriteDecision> {
  const source = resolveExternalWriteProvenanceSource(request.provenance);
  const trusted = TRUSTED_EXTERNAL_WRITE_SOURCES.includes(source);

  // Fast, purely lexical classification first: illegal sources targeting a
  // workspace-external location are rejected before any filesystem access.
  const requestedPath = lexicalTargetPath(request.targetPath, request.workspaceRoot);
  const root = path.resolve(request.workspaceRoot);
  const lexicalInside = isInsideRoot(requestedPath, root);

  if (!trusted && !lexicalInside) {
    const shape = detectResidualShape(request.targetPath);
    const escapeKind: ExternalWritePathEscapeKind =
      shape.esiduals && shape.residuals.length > 0
        ? shape.escapeKind
        : path.isAbsolute(request.targetPath)
          ? "absolute-external"
          : containsParentTraversal(request.targetPath)
            ? "parent-directory"
            : "absolute-external";
    return {
      allowed: false,
      source,
      code: `external-write-provenance-rejected:${escapeKind}`,
      reason: `Refusing workspace-external write for provenance source '${source}' (${escapeKind}).`,
      escapeKind,
      residuals: shape.residuals ?? [],
    };
  }

  const resolution = await resolveWorkspaceExternalWritePath(
    request.targetPath,
    request.workspaceRoot,
  );

  if (!trusted && resolution.outsideWorkspace) {
    return {
      allowed: false,
      source,
      code: `external-write-provenance-rejected:${resolution.escapeKind}`,
      reason: `Refusing workspace-external write for provenance source '${source}' (${resolution.escapeKind}).`,
      escapeKind: resolution.escapeKind,
      residuals: resolution.residuals,
    };
  }

  return { allowed: true, source, resolution };
}

/**
 * Assert the external write boundary. Throws `ExternalWritePolicyError` for
 * illegal workspace-external writes; otherwise returns the resolved path
 * information so the caller can perform the write unchanged.
 */
export async function assertWorkspaceExternalWriteAllowed(
  request: ExternalWritePolicyRequest,
): Promise<ExternalWritePathResolution> {
  const decision = await decideWorkspaceExternalWrite(request);
  if (!decision.allowed) {
    throw new ExternalWritePolicyError(decision.reason, {
      code: decision.code,
      source: decision.source,
      escapeKind: decision.escapeKind,
      residuals: decision.residuals,
      targetPath: request.targetPath,
    });
  }
  return decision.resolution;
}

/** Alias kept for callers using the shorter policy name. */
export const assertExternalWriteAllowed = assertWorkspaceExternalWriteAllowed;

/** Alias kept for callers using the shorter decision name. */
export const evaluateExternalWriteProvenance = decideWorkspaceExternalWrite;

/** Alias kept for callers using the shorter resolution name. */
export const resolveExternalWriteTargetPath = resolveWorkspaceExternalWritePath;

/** Alias kept for callers using the shorter source name. */
export const normalizeExternalWriteProvenanceSource =
  resolveExternalWriteProvenanceSource;
"}],"content_note":"reconstructed"}

