  /** Provenance of the write request. */
  provenance?: ExternalWriteProvenanceInput;
  /** Target path of the write (absolute or relative to the workspace root). */
  targetPath: string;
  /** Root of the workspace; writes below it keep their existing semantics. */
  workspaceRoot: string;
}

